from pathlib import Path
import json
root=Path(__file__).resolve().parent;p=root/'landscape-test/index.html';s=p.read_text('utf8')
if 'manifest.webmanifest' not in s:s=s.replace('<title>', '<link rel="manifest" href="manifest.webmanifest"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-status-bar-style" content="black-translucent"><link rel="apple-touch-icon" href="../volume-2/assets/app-icon-192.png"><title>')
if 'id="fullscreen"' not in s:s=s.replace('<details id="settings">','<button id="fullscreen" type="button" aria-label="전체화면으로 보기" aria-pressed="false">⛶ 전체화면</button><details id="settings">')
if 'id="fullscreen-help"' not in s:s=s.replace('<script src="../volume-2/clip-player.js">','<dialog id="fullscreen-help"><h2>주소창 없이 크게 보기</h2><p>이 브라우저에서는 버튼으로 전체화면을 열 수 없습니다.</p><p><b>아이폰 Safari</b><br>공유 → 홈 화면에 추가 → 웹 앱으로 열기(표시되는 경우)를 켠 뒤, 홈 화면 아이콘으로 실행하세요.</p><p><b>안드로이드</b><br>브라우저 메뉴 → 홈 화면에 추가 또는 앱 설치 후 아이콘으로 실행하세요.</p><form method="dialog"><button>닫기</button></form></dialog><script src="../volume-2/clip-player.js">')
s=s.replace('test.css?v=1','test.css?v=2').replace('test.js?v=1','test.js?v=2');p.write_text(s,encoding='utf8')
manifest={'id':'./','name':'Tiger 가로모드 테스트','short_name':'Tiger Test','start_url':'./','scope':'./','display':'standalone','display_override':['fullscreen','standalone'],'background_color':'#f5f1e8','theme_color':'#f5f1e8','icons':[{'src':'../volume-2/assets/app-icon-192.png','sizes':'192x192','type':'image/png'},{'src':'../volume-2/assets/app-icon-512.png','sizes':'512x512','type':'image/png'}]}
css=root/'landscape-test/test.css';styles=css.read_text('utf8')
